-- BAA: authoritative assessment catalog seed generated from js/question-bank.js
BEGIN;
ON CONFLICT (id) DO UPDATE SET subject=EXCLUDED.subject,chapter=EXCLUDED.chapter,topic=EXCLUDED.topic,concept=EXCLUDED.concept,difficulty=EXCLUDED.difficulty,type=EXCLUDED.type,marks=EXCLUDED.marks,time_estimate_sec=EXCLUDED.time_estimate_sec,text=EXCLUDED.text,options=EXCLUDED.options,correct_answer=EXCLUDED.correct_answer,model_answer=EXCLUDED.model_answer,explanation=EXCLUDED.explanation,common_error_type=EXCLUDED.common_error_type,updated_at=EXCLUDED.updated_at;
ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,subject=EXCLUDED.subject,chapter=EXCLUDED.chapter,total_marks=EXCLUDED.total_marks,updated_at=EXCLUDED.updated_at;
ON CONFLICT (assessment_id,question_id) DO UPDATE SET position=EXCLUDED.position;
COMMIT;
