INSERT INTO questions (id,subject,chapter,topic,concept,difficulty,type,marks,time_estimate_sec,text,options,correct_answer,model_answer,explanation,common_error_type,created_at,updated_at) VALUES
($q$q_frac_001$q$,$q$Mathematics$q$,$q$Fractions$q$,$q$Equivalent Fractions$q$,$q$equivalent-fractions$q$,$q$easy$q$,$q$mcq$q$,1,40,$q$Which fraction is equivalent to 3/4?$q$,$q$["6/8","4/3","3/8","9/16"]$q$::jsonb,$q$6/8$q$,NULL,$q$Multiplying both the numerator and denominator of 3/4 by 2 gives 6/8 — the same value, different form.$q$,$q$equivalent-fraction-scaling-error$q$,'2026-08-01T00:00:00.000Z','2026-08-01T00:00:00.000Z'),
($q$q_frac_002$q$,$q$Mathematics$q$,$q$Fractions$q$,$q$Equivalent Fractions$q$,$q$equivalent-fractions$q$,$q$easy$q$,$q$true_false$q$,1,25,$q$True or False: 2/5 and 4/10 represent the same value.$q$,$q$["True","False"]$q$::jsonb,$q$True$q$,NULL,$q$Multiplying numerator and denominator of 2/5 by 2 gives 4/10 — same value.$q$,$q$equivalent-fraction-scaling-error$q$,'2026-08-01T00:00:00.000Z','2026-08-01T00:00:00.000Z'),
($q$q_frac_003$q$,$q$Mathematics$q$,$q$Fractions$q$,$q$Adding Fractions$q$,$q$adding-unlike-fractions$q$,$q$medium$q$,$q$math$q$,3,120,$q$Calculate 1/3 + 1/4. Show your working and give the answer as a single fraction in simplest form.$q$,NULL,$q$7/12$q$,$q$Common denominator is 12. 1/3 = 4/12, 1/4 = 3/12. 4/12 + 3/12 = 7/12. 7/12 is already in simplest form (7 is prime and does not divide 12).$q$,$q$Convert to a common denominator (12) before adding: 4/12 + 3/12 = 7/12.$q$,$q$added-numerators-and-denominators-directly$q$,'2026-08-01T00:00:00.000Z','2026-08-01T00:00:00.000Z'),
($q$q_frac_004$q$,$q$Mathematics$q$,$q$Fractions$q$,$q$Adding Fractions$q$,$q$adding-unlike-fractions$q$,$q$medium$q$,$q$step_based$q$,4,150,$q$Solve step by step: 2/5 + 1/2. Show every step (common denominator, converted fractions, sum, simplification).$q$,NULL,$q$9/10$q$,$q$Step 1: LCD of 5 and 2 is 10. Step 2: 2/5 = 4/10, 1/2 = 5/10. Step 3: 4/10 + 5/10 = 9/10. Step 4: 9/10 is already simplest form. Final answer: 9/10.$q$,$q$The key step students often skip is converting both fractions to a common denominator before adding.$q$,$q$skipped-common-denominator-step$q$,'2026-08-01T00:00:00.000Z','2026-08-01T00:00:00.000Z'),
($q$q_frac_005$q$,$q$Mathematics$q$,$q$Fractions$q$,$q$Fraction Word Problems$q$,$q$fraction-word-problems$q$,$q$medium$q$,$q$written_response$q$,3,120,$q$A pizza is cut into 8 equal slices. Riya eats 3 slices and Karan eats 2 slices. What fraction of the pizza is left? Explain your reasoning.$q$,NULL,$q$3/8$q$,$q$Total eaten = 3/8 + 2/8 = 5/8. Left = 8/8 - 5/8 = 3/8. So 3/8 of the pizza is left.$q$,$q$Add the eaten fractions first (same denominator, so just add numerators), then subtract from the whole (8/8).$q$,$q$whole-pizza-not-treated-as-8/8$q$,'2026-08-01T00:00:00.000Z','2026-08-01T00:00:00.000Z'),
($q$q_alg_001$q$,$q$Mathematics$q$,$q$Algebra$q$,$q$Linear Equations$q$,$q$solving-linear-equations$q$,$q$easy$q$,$q$mcq$q$,1,40,$q$Solve for x: 2x + 5 = 15$q$,$q$["x = 5","x = 10","x = 4","x = 7.5"]$q$::jsonb,$q$x = 5$q$,NULL,$q$Subtract 5 from both sides: 2x = 10. Divide by 2: x = 5.$q$,$q$inverse-operation-error$q$,'2026-08-01T00:00:00.000Z','2026-08-01T00:00:00.000Z'),
($q$q_alg_002$q$,$q$Mathematics$q$,$q$Algebra$q$,$q$Linear Equations$q$,$q$solving-linear-equations$q$,$q$medium$q$,$q$step_based$q$,5,180,$q$Solve for x, showing every step: 3(x - 2) = 2x + 4$q$,NULL,$q$x = 10$q$,$q$Step 1: Expand: 3x - 6 = 2x + 4. Step 2: Subtract 2x from both sides: x - 6 = 4. Step 3: Add 6 to both sides: x = 10.$q$,$q$This tests expanding brackets correctly and collecting like terms on one side before isolating x. A student can use the right METHOD and still slip on the final arithmetic — that is graded as a calculation error, not a conceptual one.$q$,$q$bracket-expansion-error$q$,'2026-08-01T00:00:00.000Z','2026-08-01T00:00:00.000Z'),
($q$q_alg_003$q$,$q$Mathematics$q$,$q$Algebra$q$,$q$Linear Equations$q$,$q$solving-linear-equations$q$,$q$medium$q$,$q$true_false$q$,1,30,$q$True or False: x = -3 is a solution to the equation 4x + 12 = 0.$q$,$q$["True","False"]$q$::jsonb,$q$True$q$,NULL,$q$4(-3) + 12 = -12 + 12 = 0. Correct.$q$,$q$sign-error$q$,'2026-08-01T00:00:00.000Z','2026-08-01T00:00:00.000Z'),
($q$q_alg_004$q$,$q$Mathematics$q$,$q$Algebra$q$,$q$Word Problems$q$,$q$linear-equations-word-problems$q$,$q$hard$q$,$q$long_answer$q$,5,240,$q$The sum of two consecutive even numbers is 42. Find both numbers. Show your full method, including how you set up the equation.$q$,NULL,$q$20 and 22$q$,$q$Let the numbers be x and x+2. x + (x+2) = 42 -> 2x + 2 = 42 -> 2x = 40 -> x = 20. The numbers are 20 and 22.$q$,$q$Setting up the equation correctly (consecutive EVEN numbers differ by 2, not 1) is the main concept being tested here.$q$,$q$consecutive-number-setup-error$q$,'2026-08-01T00:00:00.000Z','2026-08-01T00:00:00.000Z'),
($q$q_geo_001$q$,$q$Mathematics$q$,$q$Geometry$q$,$q$Triangles$q$,$q$triangle-angle-sum$q$,$q$easy$q$,$q$mcq$q$,1,35,$q$Two angles of a triangle are 55° and 65°. What is the third angle?$q$,$q$["60°","70°","50°","80°"]$q$::jsonb,$q$60°$q$,NULL,$q$Angles in a triangle sum to 180°. 180 - 55 - 65 = 60°.$q$,$q$angle-sum-rule-error$q$,'2026-08-01T00:00:00.000Z','2026-08-01T00:00:00.000Z'),
($q$q_geo_002$q$,$q$Mathematics$q$,$q$Geometry$q$,$q$Triangles$q$,$q$triangle-angle-sum$q$,$q$medium$q$,$q$short_answer$q$,2,60,$q$A triangle has angles in the ratio 2:3:4. What is the size of the largest angle?$q$,NULL,$q$80°$q$,$q$Total parts = 2+3+4 = 9. Each part = 180/9 = 20°. Largest angle = 4 x 20 = 80°.$q$,$q$Divide 180° by the total number of ratio parts, then multiply by the largest part.$q$,$q$ratio-to-angle-conversion-error$q$,'2026-08-01T00:00:00.000Z','2026-08-01T00:00:00.000Z'),
($q$q_sci_001$q$,$q$Science$q$,$q$Life Processes$q$,$q$Photosynthesis$q$,$q$photosynthesis-basics$q$,$q$easy$q$,$q$mcq$q$,1,30,$q$Which gas do plants absorb from the air during photosynthesis?$q$,$q$["Carbon dioxide","Oxygen","Nitrogen","Hydrogen"]$q$::jsonb,$q$Carbon dioxide$q$,NULL,$q$Plants take in carbon dioxide and release oxygen during photosynthesis.$q$,$q$gas-exchange-direction-confusion$q$,'2026-08-01T00:00:00.000Z','2026-08-01T00:00:00.000Z'),
($q$q_sci_002$q$,$q$Science$q$,$q$Life Processes$q$,$q$Photosynthesis$q$,$q$photosynthesis-basics$q$,$q$medium$q$,$q$short_answer$q$,3,100,$q$Write the word equation for photosynthesis and name one factor that can limit its rate.$q$,NULL,$q$carbon dioxide + water -> glucose + oxygen (light/chlorophyll needed); limiting factor: light intensity / CO2 / temperature$q$,$q$Carbon dioxide + water --(light energy, chlorophyll)--> glucose + oxygen. A limiting factor could be light intensity, carbon dioxide concentration, or temperature.$q$,$q$The full equation needs both reactants and both products, plus the condition (light energy via chlorophyll).$q$,$q$incomplete-equation$q$,'2026-08-01T00:00:00.000Z','2026-08-01T00:00:00.000Z'),
($q$q_sci_003$q$,$q$Science$q$,$q$Life Processes$q$,$q$Photosynthesis$q$,$q$photosynthesis-basics$q$,$q$hard$q$,$q$written_response$q$,4,180,$q$A gardener notices that a plant kept in a dark cupboard for a week has pale, yellow leaves instead of green ones. Explain, using your knowledge of photosynthesis, why this happened.$q$,NULL,$q$Lack of light prevents photosynthesis and chlorophyll production, so leaves turn pale/yellow.$q$,$q$Without light, the plant cannot photosynthesize, so it cannot produce the energy/products needed to make chlorophyll. Without chlorophyll the leaves lose their green colour (turn pale/yellow) — this is because chlorophyll production itself depends on light.$q$,$q$This tests whether the student connects light -> photosynthesis -> chlorophyll -> leaf colour, not just recall of the word equation.$q$,$q$surface-level-explanation-without-causal-chain$q$,'2026-08-01T00:00:00.000Z','2026-08-01T00:00:00.000Z')
